    if preference.user_profile_id:
        return preference.user_profile.user_id == user.id
    if preference.family_id:
        return FamilyMembership.objects.filter(
            user=user,
            family_id=preference.family_id,
            is_admin=True,
            is_active=True,
        ).exists()
